import { View, Alert, Button } from 'react-native';

const showDialog = () => {
  Alert.alert('Alert title', 'My alert message', [
    {
      text: 'Cancel',
      onPress: () => console.log('Cancel pressed'),
      style: 'cancel',
    },
    { text: 'OK', onPress: () => console.log('OK pressed') },
  ]);
};

const showDestructiveDialog = () => {
  Alert.alert('Alert title', 'My alert message', [
    {
      text: 'Cancel',
      onPress: () => console.log('Cancel pressed'),
      style: 'cancel',
    },
    {
      text: 'Close',
      onPress: () => console.log('Close pressed'),
      style: 'destructive',
    },
    { text: 'OK', onPress: () => console.log('OK pressed') },
  ]);
};

const MyDialog = () => {
  return (
    <View>
      <Button title="2-Button alert" onPress={showDialog} />
      <Button title="3-Button alert" onPress={showDestructiveDialog} />
    </View>
  );
};

export default MyDialog;

import { useRef } from 'react';
import { Animated, Text, View, Button } from 'react-native';

const MyAnimation = () => {
  const fadeAnimation = useRef(new Animated.Value(0)).current;

  const fadeIn = () => {
    Animated.timing(fadeAnimation, {
      toValue: 1,
      duration: 5000,
      useNativeDriver: true,
    }).start();
  };

  const fadeOut = () => {
    Animated.timing(fadeAnimation, {
      toValue: 0,
      duration: 5000,
      useNativeDriver: true,
    }).start();
  };

  return (
    <View style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }}>
      <Animated.View style={{ opacity: fadeAnimation }}>
        <Text>Fading view</Text>
      </Animated.View>
      <View>
        <Button title="Fade in text" onPress={fadeIn} />
        <Button title="Fade out text" onPress={fadeOut} />
      </View>
    </View>
  );
};

export default MyAnimation;

import { useCallback } from 'react';
import { Alert, Button, Linking, View } from 'react-native';

const supportedURL = 'https://google.com';
const unsupportedURL = 'slack://open?team=123456';

type ButtonProps = { url: string; title: string };

const OpenURLButton = ({ url, title }: ButtonProps) => {
  const handleClick = useCallback(async () => {
    const supported = await Linking.canOpenURL(url);
    if (supported) {
      await Linking.openURL(url);
    } else {
      Alert.alert(`Don't know how to handle this URL: ${url}`);
    }
  }, [url]);

  return <Button title={title} onPress={handleClick} />;
};

const Links = () => {
  return (
    <View>
      <OpenURLButton title="Open Supported URL" url={supportedURL} />
      <OpenURLButton title="Open Unsupported URL" url={unsupportedURL} />
    </View>
  );
};

export default Links;

import { useState } from 'react';
import { View, Modal, Text, Button, StyleSheet } from 'react-native';

const MyModal = () => {
  const [isVisible, setIsVisible] = useState(false);

  const onModalClosed = () => {
    setIsVisible(false);
  };

  return (
    <View style={styles.centeredView}>
      <Modal
        animationType="slide"
        transparent={true}
        visible={isVisible}
        onRequestClose={onModalClosed}
      >
        <View style={[styles.centeredView, styles.modalView]}>
          <Text style={styles.textStyle}>Hello world!</Text>
          <Button title="Close Modal" onPress={onModalClosed} />
        </View>
      </Modal>
      <Button title="Show Modal" onPress={() => setIsVisible(true)} />
    </View>
  );
};

const styles = StyleSheet.create({
  centeredView: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    marginTop: 22,
  },
  modalView: {
    margin: 20,
    backgroundColor: 'white',
    borderRadius: 20,
    padding: 35,
    alignItems: 'center',
    shadowColor: '#000',
    shadowOffset: {
      height: 2,
      width: 0,
    },
  },
  textStyle: {
    fontWeight: 'bold',
    textAlign: 'center',
  },
});
export default MyModal;

import {
  PixelRatio,
  Image,
  ScrollView,
  Text,
  View,
  StyleSheet,
} from 'react-native';

const size = 50;

const cat = {
  uri: 'https://reactnative.dev/docs/assets/p_cat1.png',
  width: size,
  height: size,
};

const MyPixelRatio = () => {
  return (
    <ScrollView>
      <View style={styles.container}>
        <Text>Current pixel ratio is:</Text>
        <Text>{PixelRatio.get()}</Text>
      </View>
      <View style={styles.container}>
        <Text>Current font scale is:</Text>
        <Text>{PixelRatio.getFontScale()}</Text>
      </View>
      <View style={styles.container}>
        <Text>On this device images with a layout width of</Text>
        <Text>{size} px</Text>
        <Image source={cat} />
      </View>
      <View style={styles.container}>
        <Text>requires images with a pixel width of</Text>
        <Text>{PixelRatio.getPixelSizeForLayoutSize(size)}</Text>
        <Image
          source={cat}
          style={{
            width: PixelRatio.getPixelSizeForLayoutSize(size),
            height: PixelRatio.getPixelSizeForLayoutSize(size),
          }}
        />
      </View>
    </ScrollView>
  );
};

const styles = StyleSheet.create({
  container: {
    justifyContent: 'center',
    alignItems: 'center',
  },
});

export default MyPixelRatio;

import { useState, useCallback } from 'react';
import { RefreshControl, ScrollView, StyleSheet, Text } from 'react-native';

const MyRefreshControl = () => {
  const [isRefreshing, setIsRefreshing] = useState(false);

  const onRefresh = useCallback(() => {
    setIsRefreshing(true);
    setTimeout(() => {
      setIsRefreshing(false);
    }, 2000);
  }, []);

  return (
    <ScrollView
      refreshControl={
        <RefreshControl refreshing={isRefreshing} onRefresh={onRefresh} />
      }
    >
      <Text>Pull down to see RefreshControl indicator</Text>
    </ScrollView>
  );
};

export default MyRefreshControl;

import { useState } from 'react';
import { Button, View, Text, StatusBar, StatusBarStyle } from 'react-native';

const STYLES: StatusBarStyle[] = ['default', 'light-content', 'dark-content'];

const MyStatusBar = () => {
  const [isHidden, setIsHidden] = useState(false);
  const [statusBarStyle, setStatusBarStyle] = useState(STYLES[0]);

  const changeStatusBarVisibility = () => setIsHidden(!isHidden);

  const changeStatusBarStyle = () => {
    const styleId = STYLES.indexOf(statusBarStyle) + 1;
    setStatusBarStyle(styleId === STYLES.length ? STYLES[0] : STYLES[styleId]);
  };

  return (
    <View style={{ padding: 20 }}>
      <StatusBar
        animated={true}
        backgroundColor="#61dafb"
        barStyle={statusBarStyle}
        hidden={isHidden}
      />
      <Text>Status Bar Visibility: {isHidden ? 'hidden' : 'visible'}</Text>
      <Text>Status Bar style: {statusBarStyle}</Text>
      <View>
        <Button title="Toggle status bar" onPress={changeStatusBarVisibility} />
        <Button
          title="Change status bar style"
          onPress={changeStatusBarStyle}
        />
      </View>
    </View>
  );
};

export default MyStatusBar;
